   var fontSource=AssetDatabase.LoadAssetAtPath<Font>(Directory.GetFiles(Root+"Fonts","*.ttf")[0]);font=TMP_FontAsset.CreateFontAsset(fontSource,90,9,GlyphRenderMode.SDFAA,2048,2048,AtlasPopulationMode.Dynamic,true);font.name="Final Answer Cyrillic";AssetDatabase.CreateAsset(font,Root+"Fonts/FinalAnswerFont.asset");AssetDatabase.AddObjectToAsset(font.material,font);foreach(var atlas in font.atlasTextures)AssetDatabase.AddObjectToAsset(atlas,font);font.TryAddCharacters("АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯабвгдеёжзийклмнопрстуфхцчшщъыьэюяABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 +−×÷=?!:.,/()°←→☀☾★◆",out string missing);if(missing.Length>0)Debug.LogWarning("Font glyph fallback required: "+missing);
