   var dial=Mount("adjuster",p["adjuster"],machine.transform,"ADJUSTER");machine.Adjuster=dial.AddComponent<RotatableMechanism>();machine.Adjuster.Id="ADJUSTER";controls.Add(machine.Adjuster);
   var lamp=Mount("light",p["light"],machine.transform,"LIGHT_MODULE");machine.Indicator=lamp.AddComponent<IndicatorLight>();machine.Indicator.Id="LIGHT_MODULE";machine.Indicator.Lens=lamp.GetComponentInChildren<Renderer>();var glow=Light("Indicator glow",lamp.transform,new Vector3(0,0,0),Color.red,.4f,LightType.Point);glow.range=.32f;machine.Indicator.Glow=glow;controls.Add(machine.Indicator);glow.intensity=0;
   Mount("level_handler",m["leverBase"],machine.transform,"Lever mount");var lever=Mount("lever",m["leverHandle"],machine.transform,"LEVER_MODULE");machine.Lever=lever.AddComponent<MechanicalSwitch>();machine.Lever.Id="LEVER_MODULE";controls.Add(machine.Lever);
   var code=Mount("code_display",m["code"],machine.transform,"CODE_PANEL");machine.Code=code.AddComponent<CodeSelector>();machine.Code.Id="CODE_PANEL";controls.Add(machine.Code);machine.Code.Surface=WorldCanvas("Mechanical digits",code.transform,new Vector3(0,.255f,.275f),new Vector2(.8932f,.208f),new Vector2(600,200));
   var mount=m.Arr("hatches")[0];var hatch=new GameObject("HIDDEN_HATCH");Place(hatch.transform,mount,machine.transform);machine.HatchMount=hatch.transform;var frameSpace=new GameObject("Frame content coordinate space").transform;frameSpace.SetParent(hatch.transform,false);frameSpace.localPosition=-MachineController.SourceVector(mount["pivot"]);var frame=Model("secret_hole",frameSpace);
   var doorAnchor=new GameObject("Door hinge").transform;doorAnchor.SetParent(hatch.transform,false);var scale=m["doorScale"];doorAnchor.localScale=new Vector3((float)scale.D("x",1),(float)scale.D("y",1),(float)scale.D("z",1));doorAnchor.localPosition=-MachineController.SourceVector(mount["pivot"])+MachineController.SourceVector(m["doorOffset"])+Vector3.Scale(doorAnchor.localScale,MachineController.SourceVector(m["doorPivot"]));var door=Model("door",doorAnchor);door.transform.localPosition=-MachineController.SourceVector(m["doorPivot"]);
   machine.Hatch=hatch.AddComponent<HiddenCompartment>();machine.Hatch.Id="HIDDEN_HATCH";machine.Hatch.Door=doorAnchor;machine.Hatch.PlacementId="right";var note=WorldCanvas("Concealed access note",frameSpace,new Vector3(.10f,.35f,.20f),new Vector2(.52f,.28f),new Vector2(512,256));var paper=UIFactory.Panel("Paper",note,0,0,512,256,new Color(.73f,.66f,.49f));UIFactory.Text(paper.transform,font,"КОД ДОСТУПА",35,25,450,60,32,new Color(.14f,.12f,.09f));var hint=UIFactory.Text(paper.transform,font,"",35,88,450,135,64,new Color(.08f,.07f,.04f));machine.Hatch.Note=note.gameObject;machine.Hatch.NoteText=hint;note.gameObject.SetActive(false);controls.Add(machine.Hatch);
   var terminal=new GameObject("Central CRT",typeof(InteractiveScreen));terminal.transform.SetParent(machine.transform,false);machine.Screen=terminal.GetComponent<InteractiveScreen>();machine.Screen.Surface=WorldCanvas("CRT Canvas",terminal.transform,new Vector3(.003f,.495f,.125f),new Vector2(.258f,.167f),new Vector2(1024,640));UIFactory.Panel("Phosphor backing",machine.Screen.Surface,0,0,1024,640,new Color(.012f,.025f,.022f));machine.Screen.Initialize(font);
   var readout=WorldCanvas("Adjuster angle",machine.transform,new Vector3(.169f,.319f,.203f),new Vector2(.045f,.016f),new Vector2(220,80));machine.AngleLabel=UIFactory.Text(readout,font,"0°",0,0,220,80,54);machine.AngleLabel.alignment=TextAlignmentOptions.Center;
   Card(machine,"ANIMAL_PANEL",new[]{"CAT","OWL","WOLF","DEER"},new Vector3(0,.26f,-.28f));Card(machine,"SYMBOL_PANEL",new[]{"SUN","MOON","STAR","KEY"},new Vector3(0,.14f,-.28f));
