   PrefabUtility.SaveAsPrefabAsset(machine.gameObject,Root+"Prefabs/CommandMachine.prefab");EditorSceneManager.SaveScene(scene,Root+"Scenes/TheLastCommand.unity");
   var bootstrap=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var application=new GameObject("Final Answer — Bootstrap").AddComponent<GameManager>();application.font=font;application.audioCatalog=audio;EditorSceneManager.SaveScene(bootstrap,Root+"Scenes/Bootstrap.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Root+"Scenes/Bootstrap.unity",true),new EditorBuildSettingsScene(Root+"Scenes/TheLastCommand.unity",true)};AssetDatabase.SaveAssets();GameHallBuilder.Build();EditorSceneManager.OpenScene(Root+"Scenes/TheLastCommand.unity");Validate();Debug.Log("FINAL_ANSWER_SCENES_READY");
