  static GameObject Model(string model,Transform parent){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Art/Models/"+model+".glb");if(!asset)throw new InvalidOperationException("GLB importer did not produce prefab: "+model);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset,parent);g.name=model+" — supplied model";foreach(var renderer in g.GetComponentsInChildren<Renderer>()){var materials=renderer.sharedMaterials;for(int j=0;j<materials.Length;j++){var original=materials[j];string key=model+":"+original.name;if(!calibrated.TryGetValue(key,out var copy)){copy=new Material(original);if(copy.HasProperty("metallicFactor"))copy.SetFloat("metallicFactor",Mathf.Min(.72f,copy.GetFloat("metallicFactor")));string texture=calibration.S(key);if(texture!=""&&copy.HasProperty("metallicRoughnessTexture"))copy.SetTexture("metallicRoughnessTexture",AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Art/Textures/"+texture));AssetDatabase.CreateAsset(copy,Root+"Materials/Surface_"+model+"_"+calibrated.Count+".mat");calibrated[key]=copy;}materials[j]=copy;}renderer.sharedMaterials=materials;}foreach(var mf in g.GetComponentsInChildren<MeshFilter>(true)){if(!mf.sharedMesh)continue;var collider=mf.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=mf.sharedMesh;}return g;}
  static void Place(Transform t,JToken data,Transform parent){t.SetParent(parent,false);t.localPosition=MachineController.SourceVector(data["position"]);t.localRotation=MachineController.SourceRotation(data["rotation"]);var s=data["scale"];t.localScale=new Vector3((float)s.D("x",1),(float)s.D("y",1),(float)s.D("z",1));}
  static GameObject Mount(string model,JToken data,Transform parent,string name){var g=new GameObject(name);Place(g.transform,data,parent);var mesh=Model(model,g.transform);mesh.transform.localPosition=-MachineController.SourceVector(data["pivot"]);return g;}
  static RectTransform WorldCanvas(string name,Transform parent,Vector3 position,Vector2 size,Vector2 pixels){var g=new GameObject(name,typeof(RectTransform),typeof(Canvas),typeof(GraphicRaycaster));var rect=(RectTransform)g.transform;rect.SetParent(parent,false);rect.localPosition=position;rect.localRotation=Quaternion.Euler(0,180,0);rect.localScale=new Vector3(size.x/pixels.x,size.y/pixels.y,size.x/pixels.x);rect.sizeDelta=pixels;rect.pivot=new Vector2(.5f,.5f);g.GetComponent<Canvas>().renderMode=RenderMode.WorldSpace;g.GetComponent<GraphicRaycaster>().blockingObjects=GraphicRaycaster.BlockingObjects.ThreeD;return rect;}
  static void Tint(GameObject g,string color){foreach(var r in g.GetComponentsInChildren<Renderer>()){var materials=r.sharedMaterials;for(int i=0;i<materials.Length;i++){var mat=new Material(materials[i]);var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Art/Textures/Button_"+color+".png");foreach(string property in new[]{"baseColorTexture","_BaseColorTexture","_BaseMap","_MainTex"})if(texture&&mat.HasProperty(property))mat.SetTexture(property,texture);AssetDatabase.CreateAsset(mat,Root+"Materials/"+g.name+"_"+i+".mat");materials[i]=mat;}r.sharedMaterials=materials;}}
  static void Card(MachineController machine,string id,string[] values,Vector3 position){var root=new GameObject(id);root.transform.SetParent(machine.transform,false);root.transform.localPosition=position;root.transform.localRotation=Quaternion.Euler(0,180,0);var normalization=new GameObject("Authored tray normalization").transform;normalization.SetParent(root.transform,false);var tray=Model("animal_panel",normalization);var bounds=new Bounds();bool first=true;foreach(var r in tray.GetComponentsInChildren<Renderer>()){if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}normalization.localScale=new Vector3(.30f/bounds.size.x,.105f/bounds.size.y,.02f/bounds.size.z);normalization.localPosition=-Vector3.Scale(root.transform.InverseTransformPoint(bounds.center),normalization.localScale);var choice=root.AddComponent<ChoicePanel>();choice.Id=id;choice.Values=values;choice.Surface=WorldCanvas("Cards",root.transform,new Vector3(0,0,-.025f),new Vector2(.28f,.075f),new Vector2(800,200));controls.Add(choice);}
  static Light Light(string name,Transform parent,Vector3 p,Color color,float intensity,LightType type){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=p;var l=g.AddComponent<Light>();l.type=type;l.color=color;l.intensity=intensity;return l;}
  static void Environment(Transform machine){RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.24f,.27f,.3f);RenderSettings.ambientEquatorColor=new Color(.14f,.17f,.18f);RenderSettings.ambientGroundColor=new Color(.025f,.02f,.018f);var key=Light("Warm key",null,new Vector3(-1,2,2),new Color(1,.86f,.7f),2.0f,LightType.Directional);key.transform.rotation=Quaternion.Euler(38,-35,0);key.shadows=LightShadows.Soft;key.shadowBias=.015f;key.shadowNormalBias=.03f;var rim=Light("Amber rim",null,new Vector3(.7f,.7f,-.5f),new Color(1,.35f,.09f),.65f,LightType.Point);rim.range=2;var fill=Light("Cold fill",null,new Vector3(-.8f,.65f,.9f),new Color(.45f,.6f,.72f),1.5f,LightType.Point);fill.range=2;
   var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.name="Environment floor — supporting geometry";floor.transform.localScale=Vector3.one*.7f;floor.transform.position=new Vector3(0,-.012f,0);var metal=new Material(Shader.Find("Universal Render Pipeline/Lit"));metal.SetColor("_BaseColor",new Color(.007f,.01f,.012f));metal.SetFloat("_Metallic",.3f);metal.SetFloat("_Smoothness",.15f);AssetDatabase.CreateAsset(metal,Root+"Materials/Floor.mat");floor.GetComponent<Renderer>().sharedMaterial=metal;
   var volume=new GameObject("Horror grading / moderate bloom").AddComponent<Volume>();volume.isGlobal=true;var profile=ScriptableObject.CreateInstance<VolumeProfile>();var bloom=profile.Add<Bloom>();bloom.intensity.Override(.28f);bloom.threshold.Override(1.1f);var tone=profile.Add<Tonemapping>();tone.mode.Override(TonemappingMode.ACES);var adjust=profile.Add<ColorAdjustments>();adjust.postExposure.Override(.35f);adjust.contrast.Override(12);var vignette=profile.Add<Vignette>();vignette.intensity.Override(.22f);AssetDatabase.CreateAsset(profile,Root+"Data/MachineVolume.asset");foreach(var component in profile.components)AssetDatabase.AddObjectToAsset(component,profile);volume.sharedProfile=profile;
  }
  static AudioCatalog CreateAudio(){var manifest=JObject.Parse(File.ReadAllText(Root+"Data/audio-manifest.json"));var data=ScriptableObject.CreateInstance<AudioCatalog>();var cues=new List<AudioCatalog.Cue>();foreach(var c in manifest.Arr("cues")){string path=Root+"Audio/"+(c.B("voice")?"Voice/":"Clips/")+Path.GetFileName(c.S("file"));var importer=(AudioImporter)AssetImporter.GetAtPath(path);var settings=importer.defaultSampleSettings;settings.loadType=c.B("stream")||c.B("voice")?AudioClipLoadType.Streaming:AudioClipLoadType.DecompressOnLoad;importer.defaultSampleSettings=settings;importer.SaveAndReimport();cues.Add(new AudioCatalog.Cue{id=c.S("id"),clip=AssetDatabase.LoadAssetAtPath<AudioClip>(path),gain=(float)c.D("volume",.7),priority=(int)c.L("priority",2),throttleMs=(int)c.L("throttleMs")});}data.cues=cues.ToArray();AssetDatabase.CreateAsset(data,Root+"Data/AudioCatalog.asset");return data;}
  [MenuItem("Final Answer/Validate Scene")]
  public static void Validate(){var machine=UnityEngine.Object.FindAnyObjectByType<MachineController>();if(!machine||machine.Mechanisms.Length<11||!machine.Screen||!machine.Hatch.Door||!machine.CameraRig)throw new Exception("Incomplete machine bindings");foreach(var go in UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(go)>0)throw new Exception("Missing script: "+go.name);Debug.Log("SCENE_VALIDATION_OK: "+machine.Mechanisms.Length+" mechanisms; supplied mesh colliders; no missing scripts");}
